contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint beforeBalance = address(c).balance;
        address(c).call{value: amount}("");
        uint afterBalance = address(c).balance;
        assert(afterBalance == beforeBalance + amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public payable {
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        assert(!reverted && address(c).balance == 0);
    }
    receive() external payable {}
}
